3	import (
4		"strings"
5		"testing"
6	
7		tea "charm.land/bubbletea/v2"
8		"github.com/charmbracelet/x/ansi"
9	
10		"github.com/anthnel/devdesk/internal/ui/components"
11		"github.com/anthnel/devdesk/internal/ui/testutil"
12	)
13	
14	// DEVDESK-470 task 470.5: the path trace probes the path to a host, so Port and
15	// DNS Server of the Diagnostics form do not apply to it. Trace Path says so in
16	// the sub-level's footer instead of ignoring them silently.
17	
18	const (
19		noticePortAndDNS = "Port and DNS Server are not used by the path trace"
20		noticePortOnly   = "Port is not used by the path trace"
21		noticeDNSOnly    = "DNS Server is not used by the path trace"
22	)
23	
24	func TestTraceNoticeText(t *testing.T) {
25		tests := []struct {
26			name      string
27			port, dns string
28			want      string
29		}{
30			{"both empty", "", "", ""},
31			{"both blank", "  ", "\t ", ""},
32			{"port only", "8443", "", noticePortOnly},
33			{"port only, dns blank", "8443", "   ", noticePortOnly},
34			{"dns only", "", "9.9.9.9", noticeDNSOnly},
35			{"dns only, port blank", " ", "9.9.9.9", noticeDNSOnly},
36			{"both", "8443", "9.9.9.9", noticePortAndDNS},
37		}
38		for _, tt := range tests {
39			t.Run(tt.name, func(t *testing.T) {
40				if got := traceUnusedNotice(tt.port, tt.dns); got != tt.want {
41					t.Errorf("traceUnusedNotice(%q, %q) = %q, want %q", tt.port, tt.dns, got, tt.want)
42				}
43			})
44		}
45	}
46	
47	// traceNoticeModel fills the form and presses Trace Path; it returns the Cmd
48	// that enter returned, not yet run.
49	func traceNoticeModel(t *testing.T, host, port, dns string) (*Model, *fakeEngine, tea.Cmd) {
50		t.Helper()
51		m, fe := traceFormModel(t, true)
52		m.targetInput.SetValue(host)
53		m.portInput.SetValue(port)
54		m.dnsServerInput.SetValue(dns)
55		m.focusedField = fieldTraceButton
56		m, cmd := step(t, m, testutil.Key("enter"))
57		return m, fe, cmd
58	}
59	
60	func TestTraceNoticeShownInTheSubLevelFooterAndTheTraceIsLaunched(t *testing.T) {
61		testutil.FastTimers(t, &components.FooterMsgDuration)
62		m, fe, cmd := traceNoticeModel(t, traceLevelHost, "8443", "")
63	
64		if m.state != StateTrace || !m.pathModel.running() {
65			t.Fatalf("state=%v running=%v, want the trace launched", m.state, m.pathModel.running())
66		}
67		f := &m.pathModel.footer
68		if f.Level() != components.LevelInfo || f.Text() != noticePortOnly {
69			t.Errorf("sub-level footer = {%v %q}, want Info %q", f.Level(), f.Text(), noticePortOnly)
70		}
71		if m.footer.Text() == noticePortOnly {
72			t.Error("the notice is on the form's footer: it belongs to the sub-level's (m.pathModel.footer)")
73		}
74	
75		// The Cmd carries the launch as well as the notice's timer.
76		if fe.traceCalls != 0 {
77			t.Fatalf("trace ran inside Update (%d calls, Rule 110)", fe.traceCalls)
78		}
79		_ = testutil.Msgs(cmd)
80		if fe.traceCalls != 1 {
81			t.Errorf("trace calls = %d after the Cmd, want 1", fe.traceCalls)
82		}
83	}
84	
85	func TestTraceNoticeTracesTheTargetAlone(t *testing.T) {
86		testutil.FastTimers(t, &components.FooterMsgDuration)
87		m, fe, cmd := traceNoticeModel(t, traceLevelHost, "8443", "9.9.9.9")
88	
89		if got := m.pathModel.target.Host; got != traceLevelHost {
90			t.Errorf("traced host = %q, want %q alone", got, traceLevelHost)
91		}
92		if got := m.pathModel.target.String(); strings.Contains(got, "8443") || strings.Contains(got, "9.9.9.9") || strings.Contains(got, ":") {
93			t.Errorf("traced target = %q, want no port and no DNS server in it", got)
94		}
95		_ = testutil.Msgs(cmd)
96		if fe.resolveHost != traceLevelHost {
97			t.Errorf("resolved host = %q, want %q", fe.resolveHost, traceLevelHost)
98		}
99		if got := m.pathModel.footer.Text(); got != noticePortAndDNS {
100			t.Errorf("footer = %q, want %q", got, noticePortAndDNS)
101		}
102	}
103	
104	func TestTraceNoticeDNSOnly(t *testing.T) {
105		m, _, _ := traceNoticeModel(t, traceLevelHost, "", "9.9.9.9")
106		f := &m.pathModel.footer
107		if f.Level() != components.LevelInfo || f.Text() != noticeDNSOnly {
108			t.Errorf("footer = {%v %q}, want Info %q", f.Level(), f.Text(), noticeDNSOnly)
109		}
110	}
111	
112	func TestTraceNoticeAbsentWhenPortAndDNSAreEmpty(t *testing.T) {
113		for _, blank := range []string{"", "   "} {
114			m, _, _ := traceNoticeModel(t, traceLevelHost, blank, blank)
115			if m.state != StateTrace || !m.pathModel.running() {
116				t.Fatalf("blank %q: state=%v running=%v, want the trace launched", blank, m.state, m.pathModel.running())
117			}
118			if got := m.pathModel.footer.Text(); got != "" {
119				t.Errorf("blank %q: sub-level footer = %q, want no notice", blank, got)
120			}
121			if got := m.footer.Text(); got != "" {
122				t.Errorf("blank %q: form footer = %q, want no notice", blank, got)
123			}
124		}
125	}
126	
127	// A refused target launches nothing and says nothing about Port or DNS.
128	func TestTraceNoticeAbsentWhenTheTargetIsRefused(t *testing.T) {
129		m, fe, cmd := traceNoticeModel(t, "example.com:80", "8443", "9.9.9.9")
130	
131		if m.state != StateInput || m.pathModel.running() {
132			t.Errorf("state=%v running=%v, a refused target must launch nothing", m.state, m.pathModel.running())
133		}
134		if cmd != nil {
135			t.Errorf("a refused target returned a Cmd: %v", testutil.Msgs(cmd))
136		}
137		if fe.traceCalls != 0 || fe.resolveCalls != 0 {
138			t.Errorf("trace=%d resolve=%d, want nothing emitted", fe.traceCalls, fe.resolveCalls)
139		}
140		for name, f := range map[string]*components.FooterMessage{"form": &m.footer, "sub-level": &m.pathModel.footer} {
141			if strings.Contains(f.Text(), "not used by the path trace") {
142				t.Errorf("%s footer = %q, want no notice on a refused target", name, f.Text())
143			}
144		}
145	}
146	
147	// The notice must still be what the user reads once the sub-level renders and
148	// the trace progresses: neither the Path tab's derived status nor the hops may
149	// push it out before its own timer expires (Rule 128: info wins over status).
150	func TestTraceNoticeStaysVisibleWhileTheTraceRuns(t *testing.T) {
151		phases := map[string]func(*Model) *Model{
152			"first render": func(m *Model) *Model { return m },
153			"after hops":   func(m *Model) *Model { return traceHops(t, m, 2) },
154			"after the end": func(m *Model) *Model {
155				return traceEnded(t, traceHops(t, m, 2))
156			},
157		}
158		for name, advance := range phases {
159			m, _, _ := traceNoticeModel(t, traceLevelHost, "8443", "")
160			m = advance(m)
161			if got := ansi.Strip(m.RenderFooter(120)); !strings.Contains(got, noticePortOnly) {
162				t.Errorf("%s: footer = %q, want the notice %q visible", name, got, noticePortOnly)
163			}
164		}
165	}
166	
167	// The notice is an event with its timer: its own expiry clears it, and the
168	// sub-level then shows the trace's progress again.
169	func TestTraceNoticeExpires(t *testing.T) {
170		m, _, _ := traceNoticeModel(t, traceLevelHost, "8443", "")
171		m = traceHops(t, m, 1)
172		m = feed(t, m, components.ClearFooterMsg{ID: m.pathModel.footer.ID()})
173		if got := m.pathModel.footer.Text(); got != "" {
174			t.Errorf("footer = %q after the expiry, want the notice gone", got)
175		}
176		if got := ansi.Strip(m.RenderFooter(120)); !strings.Contains(got, "Tracing "+traceLevelHost) {
177			t.Errorf("footer = %q, want the trace progress back once the notice expired", got)
178		}
179	}
